mapper.select:
SELECT 
FROM TBL_GUARANTEE_MONITORING

    DELETE_FLAG = 0

        AND ALERT_NO LIKE CONCAT('%', #{alertNo}, '%')


        AND ALERT_TYPE = #{alertType}


        AND ALERT_LEVEL = #{alertLevel}


        AND ALERT_STATUS = #{alertStatus}


        AND COMPANY_NAME LIKE CONCAT('%', #{companyName}, '%')


ORDER BY ALERT_DATE DESC, CREATED_TIME DESC

mapper.update:
UPDATE TBL_GUARANTEE_MONITORING
ALERT_TYPE = #{alertType}, ALERT_LEVEL = #{alertLevel}, ALERT_MESSAGE = #{alertMessage}, ALERT_STATUS = #{alertStatus}, HANDLER_ID = #{handlerId}, HANDLER_NAME = #{handlerName}, HANDLE_DATE = #{handleDate}, HANDLE_OPINION = #{handleOpinion}, UPDATED_TIME = #{updatedTime}, REMARK = #{remark},
WHERE ALERT_ID = #{alertId}

UPDATE TBL_GUARANTEE_MONITORING
SET DELETE_FLAG = 1
WHERE ALERT_ID = #{alertId}
